Plan:
Copy the workbook, read cached values from Sheet1, and scan rows 4–6 across the month columns for the first two numeric entries. Compute the gap as the second numeric column minus the first numeric column, overriding the result with 1 when the first numeric value is greater than 1. Write the computed integers into N4:N6.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb["Sheet1"]
vws = vals["Sheet1"]

answer_col = 14          # N
data_start_col = 2       # B
data_end_col = 13        # M
start_row = 4
end_row = max(6, ws.max_row)

def numeric_value(v):
    if isinstance(v, bool):
        return None
    if isinstance(v, (int, float)):
        return float(v)
    if isinstance(v, str):
        s = v.strip()
        try:
            return float(s)
        except ValueError:
            return None
    return None

for r in range(start_row, end_row + 1):
    first_idx = None
    first_val = None
    second_idx = None

    for c in range(data_start_col, data_end_col + 1):
        v = vws.cell(row=r, column=c).value
        n = numeric_value(v)
        if n is None:
            continue

        if first_idx is None:
            first_idx = c
            first_val = n
        else:
            second_idx = c
            break

    if first_idx is None:
        result = 0
    elif first_val > 1:
        result = 1
    elif second_idx is None:
        result = 0
    else:
        result = second_idx - first_idx

    ws.cell(row=r, column=answer_col).value = result
    print(f"Row {r}: result={result}")

wb.save(OUT)
